boolean def sevenDayEligible(int:days, boolean:unused, boolean:sealed, boolean:impact) {
    if (days <= 7) {
        if (unused) {
            if (sealed) {
                if (impact) {
                    return false;
                } else {
                    return true;
                }
            } else {
                return false;
            }
        } else {
            return false;
        }
    } else {
        return false;
    }
}


boolean def qualityEligible(int:days, boolean:proof, boolean:shopResponsible) {
    if (days <= 15) {
        if (proof) {
            return true;
        } else {
            if (shopResponsible) {
                return true;
            } else {
                return false;
            }
        }
    } else {
        return false;
    }
}


boolean def exchangeEligible(str:reason, int:days) {
    if (reason == "SIZE") {
        if (days <= 15) {
            return true;
        } else {
            return false;
        }
    } else if (reason == "MISMATCH") {
        if (days <= 30) {
            return true;
        } else {
            return false;
        }
    } else {
        return false;
    }
}


str def freightPayer(str:reason) {
    if (reason == "QUALITY") {
        return "MERCHANT";
    } else if (reason == "MISMATCH") {
        return "MERCHANT";
    } else if (reason == "SIZE") {
        return "BUYER";
    } else if (reason == "SEVEN_DAY") {
        return "BUYER";
    } else {
        return "BUYER";
    }
}
